// Generated by Django: make_password('pw-12345678').
const djangoHash = "pbkdf2_sha256$1000000$KYvCkKOHxdEpfVxCuhGius$Z2Cb6kkY/b5M7oTqzVg7jGsj09g/w1ePPMYNCMzUFm4="

func newService(t *testing.T) (*Service, *db.Queries, *sql.DB) {
	t.Helper()
	conn, err := db.Open(context.Background(), filepath.Join(t.TempDir(), "t.db"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { conn.Close() })
	q := db.New(conn)
	return NewService(q, 14), q, conn
}

func TestDjangoHashVerifiesAndRehashes(t *testing.T) {
	if ok, rehash := VerifyPassword("pw-12345678", djangoHash); !ok || !rehash {
		t.Fatalf("django hash: ok=%v rehash=%v", ok, rehash)
	}
	if ok, _ := VerifyPassword("wrong", djangoHash); ok {
		t.Fatal("wrong password accepted")
	}
	if ok, _ := VerifyPassword("x", "!unusable"); ok {
		t.Fatal("unusable hash accepted")
	}
}

func TestArgon2RoundTrip(t *testing.T) {
	h, err := HashPassword("secret-pass")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.HasPrefix(h, "$argon2id$") {
		t.Fatal(h)
	}
	if ok, rehash := VerifyPassword("secret-pass", h); !ok || rehash {
		t.Fatalf("ok=%v rehash=%v", ok, rehash)
	}
	if ok, _ := VerifyPassword("other", h); ok {
		t.Fatal("wrong password accepted")
	}
}

func TestLoginRehashesDjangoHash(t *testing.T) {
	s, q, _ := newService(t)
	ctx := context.Background()
	u, err := q.CreateUser(ctx, db.CreateUserParams{Username: "Alice", PasswordHash: djangoHash, WebhookToken: "w", CreatedAt: "2026-01-01T00:00:00Z"})
	if err != nil {
		t.Fatal(err)
	}
	if _, _, err := s.Login(ctx, "alice", "nope", ""); err != ErrInvalidCredentials {
		t.Fatalf("want invalid credentials, got %v", err)
	}
	if _, _, err := s.Login(ctx, "ALICE", "pw-12345678", "ua"); err != nil {
		t.Fatal(err)
	}
	got, _ := q.GetUser(ctx, u.ID)
	if !strings.HasPrefix(got.PasswordHash, "$argon2id$") {
		t.Fatalf("hash not upgraded: %s", got.PasswordHash)
	}
	if _, _, err := s.Login(ctx, "alice", "pw-12345678", ""); err != nil {
		t.Fatalf("login with upgraded hash: %v", err)
	}
}

func TestLoginInactiveUser(t *testing.T) {
	s, q, conn := newService(t)
	ctx := context.Background()
	u, err := s.CreateUser(ctx, "bob", "password-1", false)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := conn.Exec("UPDATE users SET is_active = 0 WHERE id = ?", u.ID); err != nil {
		t.Fatal(err)
	}
	if _, _, err := s.Login(ctx, "bob", "password-1", ""); err != ErrInvalidCredentials {
		t.Fatalf("inactive login: %v", err)
	}
	_ = q
}

func TestSessionLifecycleAndExpiry(t *testing.T) {
	s, _, _ := newService(t)
	ctx := context.Background()
	if _, err := s.CreateUser(ctx, "carol", "password-1", false); err != nil {
		t.Fatal(err)
	}
	_, raw, err := s.Login(ctx, "carol", "password-1", "")
	if err != nil {
		t.Fatal(err)
	}
	if p, _ := s.authenticateSession(ctx, raw); p == nil || p.User.Username != "carol" {
		t.Fatal("session not recognised")
	}
	if p, _ := s.authenticateSession(ctx, "garbage"); p != nil {
		t.Fatal("garbage accepted")
	}
	// Past half-life: renewed.
	base := s.now()
	s.now = func() time.Time { return base.Add(8 * 24 * time.Hour) }
	if p, renewed := s.authenticateSession(ctx, raw); p == nil || !renewed {
		t.Fatalf("expected sliding renewal, p=%v renewed=%v", p, renewed)
	}
	// Beyond expiry (from the renewed time): gone.
	s.now = func() time.Time { return base.Add(30 * 24 * time.Hour) }
	if p, _ := s.authenticateSession(ctx, raw); p != nil {
		t.Fatal("expired session accepted")
	}
	if n, err := s.CleanupSessions(ctx); err != nil || n != 1 {
		t.Fatalf("cleanup n=%d err=%v", n, err)
	}
}

func TestTokens(t *testing.T) {
	s, _, _ := newService(t)
	ctx := context.Background()
	u, _ := s.CreateUser(ctx, "dave", "password-1", false)
	tok, err := s.CreateToken(ctx, u.ID, "kindle", ScopeWrite)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.HasPrefix(tok.Key, "axm_") || len(tok.Key) != 4+43 || tok.Prefix != tok.Key[:10] {
		t.Fatalf("token shape: %+v", tok)
	}
	p := s.authenticateToken(ctx, tok.Key)
	if p == nil || !p.CanWrite() || p.User.ID != u.ID {
		t.Fatalf("authenticate: %+v", p)
	}
	if p := s.AuthenticateMD5(ctx, "dave", strings.ToUpper(md5Hex(tok.Key))); p == nil {
		t.Fatal("md5 auth failed")
	}
	if s.authenticateToken(ctx, tok.Key+"x") != nil {
		t.Fatal("bad token accepted")
	}
	list, _ := s.ListTokens(ctx, u.ID)
	if len(list) != 1 || list[0].LastUsedAt == nil {
		t.Fatalf("list: %+v", list)
	}
	if _, err := s.RevokeToken(ctx, u.ID+1, tok.ID); err != ErrNotFound {
		t.Fatalf("revoke other user's token: %v", err)
	}
	v, err := s.RevokeToken(ctx, u.ID, tok.ID)
	if err != nil || !v.Revoked {
		t.Fatalf("revoke: %+v %v", v, err)
	}
	if s.authenticateToken(ctx, tok.Key) != nil {
		t.Fatal("revoked token accepted")
	}
}

func TestMiddlewareScopesAndCSRF(t *testing.T) {
	s, _, _ := newService(t)
	ctx := context.Background()
	u, _ := s.CreateUser(ctx, "erin", "password-1", false)
	read, _ := s.CreateToken(ctx, u.ID, "r", ScopeRead)
	write, _ := s.CreateToken(ctx, u.ID, "w", ScopeWrite)
	_, sess, _ := s.Login(ctx, "erin", "password-1", "")

	ok := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(204) })
	mux := http.NewServeMux()
	mux.Handle("/any", Require(ok))
	mux.Handle("/write", RequireWrite(ok))
	mux.Handle("/session", RequireSession(ok))
	h := s.Middleware(mux)

	do := func(method, path string, mod func(*http.Request)) *httptest.ResponseRecorder {
		r := httptest.NewRequest(method, path, nil)
		if mod != nil {
			mod(r)
		}
		w := httptest.NewRecorder()
		h.ServeHTTP(w, r)
		return w
	}
	bearer := func(k string) func(*http.Request) {
		return func(r *http.Request) { r.Header.Set("Authorization", "Bearer "+k) }
	}
	cookie := func(csrf bool) func(*http.Request) {
		return func(r *http.Request) {
			r.AddCookie(&http.Cookie{Name: SessionCookie, Value: sess})
			if csrf {
				r.AddCookie(&http.Cookie{Name: CSRFCookie, Value: "tok"})
				r.Header.Set(CSRFHeader, "tok")
			}
		}
	}
	cases := []struct {
		name   string
		method string
		path   string
		mod    func(*http.Request)
		want   int
		detail string
	}{
		{"anonymous", "GET", "/any", nil, 401, "Unauthorized"},
		{"bad bearer", "GET", "/any", bearer("axm_nope"), 401, "Unauthorized"},
		{"read token GET", "GET", "/any", bearer(read.Key), 204, ""},
		{"read token write route", "POST", "/write", bearer(read.Key), 403, "This token is read-only"},
		{"write token write route, no CSRF needed", "POST", "/write", bearer(write.Key), 204, ""},
		{"session GET", "GET", "/any", cookie(false), 204, ""},
		{"session POST without CSRF", "POST", "/write", cookie(false), 403, "CSRF check failed."},
		{"session POST with CSRF", "POST", "/write", cookie(true), 204, ""},
		{"session-only route with token", "GET", "/session", bearer(write.Key), 403, "Manage tokens from the web app"},
		{"session-only route with session", "GET", "/session", cookie(false), 204, ""},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			w := do(c.method, c.path, c.mod)
			if w.Code != c.want {
				t.Fatalf("status %d, want %d (%s)", w.Code, c.want, w.Body)
			}
			if c.detail != "" && !strings.Contains(w.Body.String(), `"detail":"`+c.detail+`"`) {
				t.Fatalf("body %s, want detail %q", w.Body, c.detail)
			}
		})
	}
}

func TestCookiesAttributes(t *testing.T) {
	s, _, _ := newService(t)
	for _, tc := range []struct {
		name   string
		mod    func(*http.Request)
		secure bool
	}{
		{"plain", func(*http.Request) {}, false},
		{"forwarded https", func(r *http.Request) { r.Header.Set("X-Forwarded-Proto", "https") }, true},
	} {
		r := httptest.NewRequest("GET", "/", nil)
		tc.mod(r)
		w := httptest.NewRecorder()
		s.SetSessionCookie(w, r, "v")
		c := w.Result().Cookies()[0]
		if !c.HttpOnly || c.SameSite != http.SameSiteLaxMode || c.Secure != tc.secure || c.MaxAge != 14*86400 {
			t.Errorf("%s: %+v", tc.name, c)
		}
	}
}
